212	import type { Metadata } from "next";
213	import { ComparisonTemplate } from "@/components/marketing/comparisontemplate/ComparisonTemplate";
214	import { COMPETITOR, FAQ } from "@/components/marketing/comparisontemplate/data";
215	import { CompetitorLogo } from "@/components/marketing/CompetitorLogo";
216	import { ReviewBadges } from "@/components/marketing/ReviewBadges";
217	import { FaqJsonLd, ProductJsonLd } from "@/components/marketing/StructuredData";
218	import { getVpsPriceBand } from "@/lib/vps-price-band";
219	import { db } from "@/lib/db";
220	
221	const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
222	const PATH = "/preview/comparison";
223	
224	/**
225	 * PREVIEW ROUTE — a template demonstration, not a live product page, so it stays
226	 * out of search (robots noindex). It still ships the complete SEO surface a real
227	 * comparison page would: full metadata (title/description/canonical/OG) plus
228	 * FAQ + Product/Offer JSON-LD, so the template can be judged as production-ready.
229	 */
230	export const metadata: Metadata = {
231	  title: "Nxeon vs DigitalOcean — an honest VPS comparison",
232	  description:
233	    "How Nxeon compares to DigitalOcean for cloud VPS hosting: pricing, NVMe storage, managed migration, support and where each one is the better fit — compared honestly, row by row.",
234	  alternates: { canonical: PATH },
235	  openGraph: {
236	    type: "article",
237	    title: "Nxeon vs DigitalOcean — an honest VPS comparison",
238	    description:
239	      "Pricing, NVMe storage, managed migration and support compared. An honest look at where each provider wins.",
240	    url: `${APP_URL}${PATH}`,
241	    images: [{ url: `${APP_URL}/logo.png` }],
242	  },
243	  // Preview surface — demonstrate the template without letting it rank.
244	  robots: { index: false, follow: false },
245	};
246	
247	// Prices track the live catalogue — read the DB-fed band on every request.
248	export const dynamic = "force-dynamic";
249	
250	export default async function Page() {
251	  // DB-fed Nxeon price band + plans, exactly like the live compare pages. Wrapped
252	  // so the preview degrades to neutral, price-free copy if the DB is unreachable.
253	  let fromLabel: string | undefined;
254	  let plans: Array<{ name: string; priceCents: number }> = [];
255	  try {
256	    const [band, planRows] = await Promise.all([
257	      getVpsPriceBand(),
258	      db.plan.findMany({
259	        where: { active: true },
260	        orderBy: { priceCents: "asc" },
261	        select: { name: true, priceCents: true },
262	      }),
263	    ]);
264	    fromLabel = band?.fromLabel;
265	    plans = planRows;
266	  } catch {
267	    /* DB unavailable — render the template without a price badge or Product schema */
268	  }
269	
270	  return (
271	    <>
272	      <FaqJsonLd items={FAQ} />
273	      {plans.length > 0 ? <ProductJsonLd plans={plans} /> : null}
274	      <ComparisonTemplate
275	        nxeonLogo={<CompetitorLogo slug="nxeon" name="Nxeon" size={26} />}
276	        competitorLogo={<CompetitorLogo slug={COMPETITOR.slug} name={COMPETITOR.name} size={26} />}
277	        reviewBadges={<ReviewBadges />}
278	        fromLabel={fromLabel}
279	      />
280	    </>
281	  );
282	}
